export interface LegalTermExplanation {
  term: string;
  plainMeaning: string;
  example?: string;
}

/** A real, citable statutory source backing an entry's plainSummary/keyTerms/degreeContext.
 *  `jurisdiction` is a state postal code, "federal", or "MPC" (Model Penal Code, used for
 *  doctrinal entries that are uniform-by-design rather than state-specific). */
export interface ChargeExplanationSource {
  citation: string;
  jurisdiction: string;
  url?: string;
}

export interface ChargeExplanation {
  chargePattern: RegExp;
  /** Stable identifier matching the shared/criminal-charge-citations.ts slug convention
   *  (the part after the state prefix, e.g. "ny-murder-in-the-first-degree" -> this slug is
   *  "murder-in-the-first-degree"). Used to join against
   *  shared/charge-explanation-jurisdiction-overlay.ts for per-state detail. */
  slug: string;
  plainSummary: string;
  keyTerms: LegalTermExplanation[];
  degreeContext?: string;
  /** Absent means unverified/not yet sourced. Same convention as
   *  shared/criminal-charges.ts and shared/jurisdiction-procedure-rules.ts. */
  sources?: ChargeExplanationSource[];
  dataConfidence?: 'high' | 'medium' | 'low';
  /** YYYY-MM */
  lastVerified?: string;
  notes?: string;
  /** True for every entry that has not yet been reviewed by a licensed criminal
   *  defense attorney. Distinct from `dataConfidence`, which reflects statutory-
   *  source quality and may be high even when attorney review is still pending.
   *  When true, the UI and PDF both show a visible "not yet attorney-reviewed"
   *  warning. Set to false (or omit) only after a licensed attorney has signed
   *  off and added a review comment to the entry. */
  pendingAttorneyReview?: boolean;
}

